// Read what came back. In DISCOVERY mode, read it and write nothing.
//
// MEMORY. This node walks the payload ONCE and keeps only the small fields it
// needs. It never stringifies the response and never builds a second array of
// events - against the 26 MB discovery response that is the difference between
// a report and an out-of-memory.

const build = $('Build requests').all().map(i => i.json);
const mode  = (build[0] && build[0].mode) || 'targeted';
const cfg   = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json);

/** Walk every event in the response without concatenating them. */
function* eachEvent() {
  for (const it of $('Fetch markets').all()) {
    const j = it.json;
    if (!j) continue;
    const list = Array.isArray(j) ? j
               : (Array.isArray(j.data) ? j.data : (Array.isArray(j.events) ? j.events : null));
    if (list) { for (const ev of list) yield ev; } else { yield j; }
  }
}

// Turn one real slug into the template, so nobody has to hand-place the
// placeholders. That step is where this goes wrong: "replace the city with
// {city}" sounds simple and is exactly what a person gets subtly wrong.
//
// Given  highest-temperature-in-nyc-on-september-6
// and a cities table containing nyc,
// it returns  highest-temperature-in-{city}-on-{month}-{day}
// plus the override needed when the slug's word is not the city_key.
const MONTHS = ['january','february','march','april','may','june',
                'july','august','september','october','november','december'];

function deriveTemplate(slug, cities) {
  let t = String(slug);
  const notes = [];
  let cityWord = null, matched = null;

  // 1. the month name, longest first so "may" cannot match inside another word
  let monthFound = null;
  for (const m of [...MONTHS].sort((a, b) => b.length - a.length)) {
    const re = new RegExp('(^|-)' + m + '(-|$)');
    if (re.test(t)) { t = t.replace(re, '$1{month}$2'); monthFound = m; break; }
  }
  // 2. the day number, which follows the month in every layout seen
  if (monthFound) {
    t = t.replace(/\{month\}-(\d{1,2})(-|$)/, '{month}-{day}$2');
  } else {
    // an ISO date instead of a month name
    if (/(^|-)(\d{4})-(\d{2})-(\d{2})(-|$)/.test(t)) {
      t = t.replace(/(^|-)\d{4}-\d{2}-\d{2}(-|$)/, '$1{date}$2');
      notes.push('this market uses an ISO date, so the template uses {date}');
    }
  }

  // 3. the city. Try every name we know for every city, longest first, so
  //    "new-york" wins over "york".
  const candidates = [];
  for (const c of cities) {
    for (const nm of [c.display_name, c.city_key, c.icao]) {
      if (!nm) continue;
      const s = String(nm).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
      if (s) candidates.push({ city: c, s });
    }
  }
  candidates.sort((a, b) => b.s.length - a.s.length);
  for (const cand of candidates) {
    const re = new RegExp('(^|-)' + cand.s + '(-|$)');
    if (re.test(t)) { t = t.replace(re, '$1{city}$2'); matched = cand.city; cityWord = cand.s; break; }
  }

  // 4. no city matched: the slug names it differently. Say which word it is,
  //    which is the thing city_slug_overrides exists for.
  if (!matched) {
    const m = t.match(/-in-([a-z0-9-]+?)-on-/) || t.match(/^([a-z0-9-]+?)-(?:on|{month})/);
    cityWord = m ? m[1] : null;
    if (cityWord) {
      t = t.replace(new RegExp('(^|-)' + cityWord + '(-|$)'), '$1{city}$2');
      notes.push(`the slug calls the city "${cityWord}", which is not one of your city keys - ` +
                 `add an override, e.g. {"<your_city_key>":"${cityWord}"}`);
    } else {
      notes.push('could not tell which part of the slug is the city - set slug_template by hand');
    }
  }

  return { template: t, city_word: cityWord, matched_city: matched ? matched.city_key : null,
           month_found: monthFound, notes,
           complete: t.includes('{city}') && (t.includes('{month}') || t.includes('{date}')) };
}

// ---- DERIVE: one real slug in, a working template out --------------------
if (mode === 'derive') {
  const want = String(build[0].slug || '').toLowerCase();
  let found = null;
  for (const ev of eachEvent()) {
    if (!ev) continue;
    if (String(ev.slug || '').toLowerCase() === want) { found = ev; break; }
    if (!found) found = ev;                    // some responses do not echo the slug
  }
  const derived = deriveTemplate(build[0].slug, cities);
  const inner = found && Array.isArray(found.markets) ? found.markets : [];
  return [{ json: {
    mode: 'derive',
    asked_slug: build[0].slug,
    got_event: Boolean(found),
    n_buckets: inner.length,
    sample_buckets: inner.slice(0, 4).map(m => m && (m.groupItemTitle || m.question) || null),
    end_date: found ? (found.endDate || found.end_date || null) : null,
    derived,
    markets: [], bands: [], n_markets: 0, n_bands: 0,
    skipped_no_city: 0, band_parse_failed: 0, failed_labels: [], dates: [],
  }}];
}

// ---- DISCOVERY: report the real slug format, write nothing ---------------
if (mode === 'discovery') {
  const LOOKS_LIKE = /temperature|temp-in|highest-temp|weather|degrees/i;
  const samples = [];
  const cityWords = new Set();
  let nEvents = 0;

  for (const ev of eachEvent()) {
    if (!ev) continue;
    nEvents++;
    const slug = String(ev.slug || ev.event_slug || '');
    if (!slug || !LOOKS_LIKE.test(slug)) continue;
    if (samples.length < 25) {
      samples.push({
        slug,
        end_date: ev.endDate || ev.end_date || null,
        n_markets: Array.isArray(ev.markets) ? ev.markets.length : 0,
        first_bucket: (Array.isArray(ev.markets) && ev.markets[0])
          ? (ev.markets[0].groupItemTitle || ev.markets[0].question || null) : null,
      });
    }
    // Pull the word that sits where the city goes, so a city_key that does not
    // appear in the slug is visible as the mismatch it is.
    const m = slug.match(/(?:temperature|temp)-in-([a-z0-9-]+?)-on-/i);
    if (m) cityWords.add(m[1]);
  }

  // Paging that is not honoured returns the same events every time, which
  // looks like "there are only 20 markets on Polymarket" and is not.
  const allSlugs = [];
  for (const ev of eachEvent()) if (ev && ev.slug) allSlugs.push(String(ev.slug));
  const distinct = new Set(allSlugs).size;
  const pagingWorks = build.length < 2 || distinct > Math.ceil(allSlugs.length / build.length) + 1;

  return [{ json: {
    mode: 'discovery',
    n_events: nEvents,
    n_distinct_slugs: distinct,
    n_pages_asked: build.length,
    paging_works: pagingWorks,
    n_temperature_events: samples.length,
    samples,
    derived: samples.length ? deriveTemplate(samples[0].slug, cities) : null,
    city_words: Array.from(cityWords).sort(),
    your_city_keys: cities.map(c => c.city_key).slice(0, 60),
    markets: [], bands: [], n_markets: 0, n_bands: 0,
    skipped_no_city: 0, band_parse_failed: 0, failed_labels: [], dates: [],
  }}];
}

// ---- TARGETED -------------------------------------------------------------
const MAX_EVENTS = Math.max(1, Number(cfg.max_events || 200));
const MAX_BANDS  = Math.max(1, Number(cfg.max_bands || 4000));

// markets.market_id and bands.band_id are uuid columns, and Polymarket's own
// ids are numeric strings and 0x hex - neither is a uuid. They must also be
// STABLE across runs or every run inserts duplicates instead of upserting.
function uuidFrom(str) {
  const s = String(str);
  let h = '';
  for (let salt = 0; salt < 4; salt++) {
    let v = 0x811c9dc5 ^ salt;
    for (let i = 0; i < s.length; i++) { v ^= s.charCodeAt(i); v = Math.imul(v, 0x01000193) >>> 0; }
    h += v.toString(16).padStart(8, '0');
  }
  return [h.slice(0,8), h.slice(8,12), '4'+h.slice(13,16),
          ((parseInt(h[16],16) & 0x3 | 0x8).toString(16))+h.slice(17,20), h.slice(20,32)].join('-');
}

// Polymarket states the bucket in TEXT, and band_lo/band_hi are what the
// probability lattice, every edge and band_contains() in ad4_34 all read. A
// band with null bounds cannot be priced. Half-open [lo, hi): "70-71F" settles
// on an integer high of 70 or 71, so it is [70, 72).
function parseBucket(text) {
  if (!text) return null;
  const t = String(text).replace(/[°℉℃]/g, ' ').replace(/[–—]/g, '-').toLowerCase()
                        .replace(/(\d)\s*[fc](?![a-z])/g, '$1')
                        .replace(/\s+/g, ' ').trim();
  const num = '(-?\\d+(?:\\.\\d+)?)';
  let m = t.match(new RegExp('^' + num + '\\s*(?:-|to)\\s*' + num));
  if (m) {
    const lo = parseFloat(m[1]), hi = parseFloat(m[2]);
    const step = Number.isInteger(lo) && Number.isInteger(hi) ? 1 : 0;
    return { lo, hi: hi + step, open_low: false, open_high: false };
  }
  m = t.match(new RegExp('^' + num + '\\s*(?:\\+|or (?:above|higher|more)|and (?:above|up|higher))'))
      || t.match(new RegExp('^(?:above|over|at least|greater than)\\s*' + num));
  if (m) return { lo: parseFloat(m[1]), hi: null, open_low: false, open_high: true };
  m = t.match(new RegExp('^' + num + '\\s*(?:-|or (?:below|less|lower|fewer))'))
      || t.match(new RegExp('^(?:below|under|less than|at most)\\s*' + num));
  if (m) {
    const v = parseFloat(m[1]);
    return { lo: null, hi: /or (below|less|lower|fewer)/.test(t) ? v + 1 : v,
             open_low: true, open_high: false };
  }
  m = t.match(new RegExp('^' + num + '\\s*$'));
  if (m) {
    const v = parseFloat(m[1]);
    return { lo: v, hi: Number.isInteger(v) ? v + 1 : v, open_low: false, open_high: false };
  }
  return null;
}

// Gamma gives endDate, and for a US market that is typically 04:00-05:00 UTC on
// the day AFTER the local trading day. Rolling an early-UTC end time back one
// day recovers the local day. Check the dates the Summary prints on the first
// run: getting this wrong shifts every market by a day and nothing downstream
// can tell.
function resolutionDate(ev, fallback) {
  const months = ['january','february','march','april','may','june','july','august','september','october','november','december'];
  const text = String(ev.slug || '').toLowerCase();
  const m = text.match(/-on-([a-z]+)-(\d{1,2})(?:-(\d{4}))?(?:$|-)/);
  if (!m || !months.includes(m[1])) return null;
  const reference = new Date(ev.endDate || ev.end_date || fallback);
  if (isNaN(reference.getTime())) return null;
  const years = m[3] ? [Number(m[3])] : [reference.getUTCFullYear()-1,reference.getUTCFullYear(),reference.getUTCFullYear()+1];
  const candidates = years.map(y=>new Date(Date.UTC(y,months.indexOf(m[1]),Number(m[2]))))
    .filter(d=>d.getUTCMonth()===months.indexOf(m[1]) && d.getUTCDate()===Number(m[2]));
  candidates.sort((a,b)=>Math.abs(a-reference)-Math.abs(b-reference));
  const date=candidates[0];
  return date && Math.abs(date-reference)<7*86400000 ? date.toISOString().slice(0,10) : null;
}

function tokensOf(mk) {
  let raw = mk.clobTokenIds ?? mk.clob_token_ids ?? mk.tokens ?? null;   // a JSON STRING, not an array
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch { raw = null; } }
  if (!Array.isArray(raw)) return [null, null];
  const n = raw.map(t => (t && typeof t === 'object') ? (t.token_id ?? t.tokenId ?? null) : t);
  return [n[0] ?? null, n[1] ?? null];
}

// Each request was built for a known city and day, so the response is matched
// back to the request that asked for it rather than guessed at from the slug.
const asked = new Map();
for (const b of build) if (b && b.slug) asked.set(String(b.slug).toLowerCase(), b);
const byKey = new Map(cities.map(c => [c.city_key, c]));

const markets = [], bands = [];
let nEvents = 0, skippedNoCity = 0, bandParseFailed = 0, capped = false, notFound = 0;
const failedLabels = [], datesSeen = new Set(), missedSlugs = [];

for (const ev of eachEvent()) {
  if (!ev || typeof ev !== 'object') continue;
  nEvents++;
  if (markets.length >= MAX_EVENTS || bands.length >= MAX_BANDS) { capped = true; break; }

  const slug = String(ev.slug || ev.event_slug || '');
  const req  = asked.get(slug.toLowerCase());
  const city = req ? byKey.get(req.city_key) : null;
  if (!city) { skippedNoCity++; continue; }

  const inner = Array.isArray(ev.markets) ? ev.markets : [];
  if (inner.length === 0) continue;

  const forDate  = resolutionDate(ev, req.for_date);
  if (forDate) datesSeen.add(forDate);
  const marketId = uuidFrom('ad4:market:' + (slug || ev.id));
  const before   = bands.length;

  for (let idx = 0; idx < inner.length; idx++) {
    if (bands.length >= MAX_BANDS) { capped = true; break; }
    const mk = inner[idx];
    if (!mk) continue;
    const label = mk.groupItemTitle || mk.group_item_title || mk.outcome || mk.question || '';
    const b = parseBucket(label)
           || parseBucket(String(mk.question || '').replace(/^.*\bbe\b\s*/i, '').replace(/\?\s*$/, ''));
    if (!b) {
      bandParseFailed++;
      if (failedLabels.length < 5) failedLabels.push(String(label).slice(0, 60));
      continue;
    }
    const [yes, no] = tokensOf(mk);
    bands.push({
      band_id: uuidFrom('ad4:band:' + (mk.conditionId || mk.condition_id || (slug + ':' + idx))),
      market_id: marketId, band_index: idx,
      band_label: String(label).trim() || null,
      band_lo: b.lo, band_hi: b.hi, open_low: b.open_low, open_high: b.open_high,
      condition_id: mk.conditionId || mk.condition_id || null,
      token_yes: yes, token_no: no,
    });
  }

  if (bands.length === before) continue;
  markets.push({
    market_id: marketId, city_key: city.city_key, resolution_date: forDate,
    event_slug: slug || null, title: ev.title || ev.question || null,
    unit: /(?:°\s*F|℉|fahrenheit)/i.test(bands.slice(before).map(b=>b.band_label).join(' ')) ? 'F' : /(?:°\s*C|℃|celsius)/i.test(bands.slice(before).map(b=>b.band_label).join(' ')) ? 'C' : (city.unit || null), band_count: bands.length - before,
    closed: Boolean(ev.closed), condition_id: ev.conditionId || ev.condition_id || null,
    last_seen_at: new Date().toISOString(),
  });
}

// Which slugs we asked for and got nothing back for - the number that says
// whether the template is right.
const got = new Set(markets.map(m => String(m.event_slug || '').toLowerCase()));
for (const [slug] of asked) if (!got.has(slug)) { notFound++; if (missedSlugs.length < 5) missedSlugs.push(slug); }

// band_index is the ladder position, not the order Polymarket listed them.
const byMarket = {};
for (const b of bands) (byMarket[b.market_id] = byMarket[b.market_id] || []).push(b);
for (const list of Object.values(byMarket)) {
  list.sort((x, y) => (x.band_lo ?? -1e9) - (y.band_lo ?? -1e9));
  list.forEach((b, i) => { b.band_index = i; });
}
// band_count is what the desk can PRICE. The overround check sums a ladder and
// reads a short one as a cheap book.
for (const m of markets) m.band_count = (byMarket[m.market_id] || []).length;

return [{ json: {
  mode: 'targeted', markets, bands,
  n_markets: markets.length, n_bands: bands.length, n_events: nEvents,
  n_requested: asked.size, not_found: notFound, missed_slugs: missedSlugs,
  skipped_no_city: skippedNoCity, band_parse_failed: bandParseFailed,
  failed_labels: failedLabels, dates: Array.from(datesSeen).sort(),
  capped, n_raw: nEvents,
}}];

const p = $('Parse markets + bands').first().json;

// ---- DERIVE: one link in, a ready-to-paste template out -----------------
if (p.mode === 'derive') {
  if (!p.got_event) {
    throw new Error(
      `Asked Polymarket for the slug "${p.asked_slug}" and it returned no event.\n\n` +
      `Either the address you pasted into example_event_url is not a market page, or ` +
      `event_url_template is wrong for your account. It is currently:\n` +
      `  ${$('Config').first().json.event_url_template}\n\n` +
      `Open the market on polymarket.com, copy the WHOLE address bar, and paste it into ` +
      `example_event_url. Nothing was written.`);
  }
  const d = p.derived;
  if (!d.complete) {
    throw new Error(
      `Fetched "${p.asked_slug}" (${p.n_buckets} buckets) but could not work out the pattern.\n` +
      `Best effort: ${d.template}\n` +
      `${d.notes.join('\n')}\n\n` +
      `Set slug_template by hand using {city} {month} {day} - or {date} for an ISO date. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `READY - copy the line below into slug_template in Config, then run again.\n\n` +
    `    ${d.template}\n\n` +
    (d.matched_city
      ? `That slug is your city "${d.matched_city}", so no override is needed.\n`
      : `ALSO: ${d.notes.join(' ')}\n`) +
    `\nConfirmed from the live event: ${p.n_buckets} buckets, ` +
    `e.g. ${p.sample_buckets.filter(Boolean).slice(0, 3).join(' | ')}` +
    (p.end_date ? `, ending ${p.end_date}` : '') + `.\n` +
    `Nothing was written - this run existed to work out that one line.`);
}

// ---- SCAN ----------------------------------------------------------------
if (p.mode === 'discovery') {
  if (p.n_temperature_events === 0) {
    throw new Error(
      `Walked ${p.n_pages_asked} page(s) of Polymarket and saw ${p.n_distinct_slugs} distinct ` +
      `event(s), none of them temperature markets.` +
      (p.paging_works === false
        ? `\n\nAND PAGING IS NOT WORKING: every page came back with the same events, so this ` +
          `will never see past the first ${p.n_distinct_slugs}. Gamma is not honouring offset.`
        : '') +
      `\n\nSTOP TRYING TO SEARCH FOR THEM. Do this instead, it takes ten seconds:\n\n` +
      `  1. Open polymarket.com and find any daily temperature market.\n` +
      `  2. Copy the whole address bar.\n` +
      `  3. Paste it into  example_event_url  in the Config node.\n` +
      `  4. Run this workflow again.\n\n` +
      `It will fetch that one event, work out the slug pattern for every city and day, and ` +
      `print the exact line to paste into slug_template. Nothing was written.`);
  }
  const lines = p.samples.slice(0, 8).map(s =>
    `    ${s.slug}   (${s.n_markets} buckets, first: ${s.first_bucket || '?'})`).join('\n');
  const d = p.derived;
  throw new Error(
    `FOUND THEM - nothing was written, which is what this mode is for.\n\n` +
    `${p.n_temperature_events} temperature event(s) out of ${p.n_distinct_slugs}:\n\n${lines}\n\n` +
    (d && d.complete
      ? `Copy this into slug_template in Config, then run again:\n\n    ${d.template}\n\n` +
        (d.matched_city ? `That slug is your city "${d.matched_city}".\n` : `ALSO: ${d.notes.join(' ')}\n`)
      : `The city appears as: ${p.city_words.join(', ') || '(could not tell)'}\n` +
        `Your cities table uses: ${p.your_city_keys.join(', ')}\n` +
        `Set slug_template by hand with {city} {month} {day}.\n`));
}

// ---- TARGETED ------------------------------------------------------------
if (p.n_markets === 0) {
  throw new Error(
    `Asked Polymarket for ${p.n_requested} event slug(s) and got no usable market back ` +
    `(${p.not_found} returned nothing). Nothing was written. slug_template is wrong for at ` +
    `least the city part. Slugs that came back empty: ${(p.missed_slugs || []).join(', ')}.\n\n` +
    `Clear slug_template, paste a real market address into example_event_url, and run again - ` +
    `it will work the pattern out from that one link.`);
}

// A BAND WITH NO NUMERIC BOUNDS CANNOT BE PRICED. Not by the probability
// lattice, not by any edge, not by band_contains() in ad4_34. Writing a ladder
// with holes in it is worse than writing nothing: the overround check reads it
// as a cheap book and every coverage figure computed from it is wrong.
const attempted = (p.n_bands || 0) + (p.band_parse_failed || 0);
if (attempted > 0 && p.band_parse_failed > attempted / 2) {
  throw new Error(
    `${p.band_parse_failed} of ${attempted} buckets had a label this workflow could not read, ` +
    `so their bounds would be null and nothing downstream can price them. Nothing was written. ` +
    `Labels it choked on: ${(p.failed_labels || []).join(' | ')}. Fix parseBucket() in ` +
    `"Parse markets + bands" - the patterns are at the top of the node.`);
}

return [{ json: p }];

const AD4_WRITE_NODES = ["Upsert markets", "Upsert bands"];
// AD4-WRITE-GUARD
// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node in this workflow carries onError=continueRegularOutput so
// that one bad row cannot kill a run. The cost of that is a REFUSED write
// walks straight past it and arrives here looking healthy - which is how a
// workflow reports "ok, 0 rows" for days while the data quietly stops moving.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named. That is what this does.
function ad4WriteError(node) {
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    if (b.error && !b.code) return { node, code: null, message: String(b.error).slice(0, 300) };
    if (b.code || b.message) {
      return { node, code: b.code ?? null, message: b.message ?? '',
               details: b.details ?? null, hint: b.hint ?? null };
    }
  }
  return null;
}

for (const node of AD4_WRITE_NODES) {
  const e = ad4WriteError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never in the code.
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write at "${e.node}": ${e.message} (${e.code}). The key was ` +
      `already checked at "Run now?" and claims to be the service key, so this is the ` +
      `DATABASE side: service_role has no INSERT on that table. Run sql/ad4_38_grants.sql ` +
      `in the Supabase SQL editor - it grants the write path back, then prints one row per ` +
      `ingest table saying whether the service key can write it. Nothing was written.`);
  }
  if (String(e.code) === '42P01') {
    throw new Error(
      `Supabase has no such table for "${e.node}": ${e.message}. The sql/ files that create ` +
      `it have not been run - sql/ad4_98_ui_health.sql names which file owns which table. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Parse markets + bands').first().json;
const rows = (p.n_markets || 0) + (p.n_bands || 0);
const failed = p.band_parse_failed || 0;

// CHECK THE DATES ON THE FIRST RUN. They come from endDate rolled back a day
// when it lands before noon UTC; if they are all one day out, that rule is a
// single function at the top of the parse node.
const summary =
  `AD4 P0.2: ${p.n_markets} market(s), ${p.n_bands} band(s) from ${p.n_requested} slug(s) asked for` +
  (p.not_found ? `, ${p.not_found} of which returned nothing` : '') + '. ' +
  `Settlement dates: ${(p.dates || []).join(', ') || 'none'}.` +
  (failed ? ` ${failed} bucket label(s) unreadable: ${(p.failed_labels || []).join(' | ')}.` : '');

const status = rows > 0 ? ((failed || p.not_found) ? 'attention' : 'ok') : 'attention';
const detail = { n_markets: p.n_markets, n_bands: p.n_bands, n_requested: p.n_requested,
                 not_found: p.not_found, missed_slugs: p.missed_slugs || [],
                 band_parse_failed: failed, failed_labels: p.failed_labels || [],
                 dates: p.dates || [], capped: p.capped };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P0.2_market_discovery', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
}}];

// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// AN ENDPOINT THIS FILE CANNOT KNOW.
//
// P0.2-P0.5 are RECONSTRUCTIONS. The Supabase half is grounded in the real
// schema and is safe; the Polymarket half never was. These files used to ship
// with a plausible-looking URL already filled in, which is worse than shipping
// none: it reads as authoritative, so nobody changes it, and the run dies four
// nodes later with a message about response shapes. That is exactly how this
// wasted an afternoon.
//
// So the field ships EMPTY and the run stops here - before any HTTP call,
// before any database read - saying where the real value is.
{
  const cfg = $('Config').first().json ?? {};
  const missing = Object.keys(cfg)
    .filter((k) => k.endsWith('_url') && k !== 'supabase_url')
    .filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty, and this file cannot fill it in. ` +
      `Open your OWN working P0.2-P0.5 in n8n, click its Polymarket HTTP node, copy the URL ` +
      `from it, and paste it here. Those workflows are what put 841 markets and 122,000 trades ` +
      `in this database - they are the authority on the endpoint, not this reconstruction. ` +
      `Nothing was fetched and nothing was written.`);
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// Decide what to ask Polymarket for.
//
// THE HISTORY, because it explains the shape of this node. Three versions
// listed events and filtered client-side, and Gamma ignored every narrowing
// parameter tried:
//
//     ?limit=200&tag_slug=weather   -> assumed 200
//     ?limit=40                     -> 2160 events, 26 MB, n8n out of memory
//     ?closed=false                 -> 20 events, none of them weather
//
// The limit is not honoured and the default page is 20. Guessing at the right
// parameter name has cost four runs, so this node stops guessing and asks for
// the one thing only you can supply: A LINK. Open polymarket.com, find any
// daily temperature market, copy the address bar into `example_event_url`.
// From that one URL the workflow derives the slug pattern itself.
//
// THREE MODES, chosen automatically:
//
//   TARGETED   slug_template is set. One URL per city per day, by name.
//              Bounded by construction. This is the steady state.
//   DERIVE     example_event_url is set and slug_template is not. Fetches that
//              one event, works out the pattern, prints it. Writes nothing.
//   SCAN       neither is set. Walks a few pages looking for temperature slugs
//              so you may not need the link at all. Writes nothing.

const cfg    = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json);

const template = String(cfg.slug_template || '').trim();
const example  = String(cfg.example_event_url || '').trim();
const urlTmpl  = String(cfg.event_url_template || 'https://gamma-api.polymarket.com/events?slug={slug}').trim();

/** The slug is the last non-empty path segment of a polymarket.com URL. */
function slugFromUrl(u) {
  const s = String(u).split('?')[0].split('#')[0].replace(/\/+$/, '');
  const parts = s.split('/').filter(Boolean);
  return parts.length ? parts[parts.length - 1] : '';
}

// ---- DERIVE ---------------------------------------------------------------
if (!template && example) {
  const slug = slugFromUrl(example);
  if (!slug || /^https?:$/.test(slug)) {
    throw new Error(
      `Could not read a slug out of example_event_url (${example}). Paste the whole address of a ` +
      `Polymarket market page - the slug is the part after /event/. Nothing was written.`);
  }
  return [{ json: { mode: 'derive', slug, url: urlTmpl.replace(/\{slug\}/g, encodeURIComponent(slug)) } }];
}

// ---- SCAN -----------------------------------------------------------------
if (!template) {
  const base  = String(cfg.discovery_url || 'https://gamma-api.polymarket.com/events?closed=false').trim();
  const pages = Math.max(1, Math.min(20, Number(cfg.discovery_pages || 8)));
  const step  = Math.max(1, Number(cfg.discovery_page_size || 20));
  const sep   = base.includes('?') ? '&' : '?';
  const out = [];
  for (let i = 0; i < pages; i++) {
    out.push({ json: { mode: 'discovery', page: i, url: `${base}${sep}offset=${i * step}` } });
  }
  return out;
}

// ---- TARGETED -------------------------------------------------------------
const MONTHS = ['january','february','march','april','may','june',
                'july','august','september','october','november','december'];

// Polymarket names a city the way a person would, which is not always the key
// this desk uses. display_name is the better guess; the override map is the
// answer when neither is right.
let overrides = {};
try { overrides = JSON.parse(String(cfg.city_slug_overrides || '{}')); } catch { overrides = {}; }

function citySlug(c) {
  if (overrides[c.city_key]) return String(overrides[c.city_key]);
  const name = c.display_name || c.city_key;
  return String(name).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

const days   = Math.max(1, Math.min(14, Number(cfg.days_ahead || 2)));
const maxReq = Math.max(1, Number(cfg.max_requests || 120));

const out = [];
const today = new Date();
for (let d = 0; d < days && out.length < maxReq; d++) {
  const dt = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() + d));
  const month = MONTHS[dt.getUTCMonth()];
  const day   = String(dt.getUTCDate());
  const iso   = dt.toISOString().slice(0, 10);
  for (const c of cities) {
    if (out.length >= maxReq) break;
    if (!c || !c.city_key) continue;
    const slug = template
      .replace(/\{city\}/g, citySlug(c))
      .replace(/\{month\}/g, month)
      .replace(/\{month_num\}/g, String(dt.getUTCMonth() + 1).padStart(2, '0'))
      .replace(/\{day\}/g, day)
      .replace(/\{day_pad\}/g, day.padStart(2, '0'))
      .replace(/\{date\}/g, iso)
      .replace(/\{year\}/g, String(dt.getUTCFullYear()));
    out.push({ json: { mode: 'targeted', city_key: c.city_key, for_date: iso, slug,
                       url: urlTmpl.replace(/\{slug\}/g, encodeURIComponent(slug)) } });
  }
}

if (out.length === 0) {
  throw new Error('No requests to make - the cities table is empty. Nothing was written.');
}
return out;
